struct Node;                                     /* recursive variant needs indirection */
using NodePtr = std::shared_ptr<Node>;
struct Node { std::variant<std::string, std::vector<NodePtr>> payload; };

struct Frame { NodePtr parent; std::size_t index; };          /* the hole at one level */
struct Loc   { NodePtr focus; std::vector<Frame> path; };
Loc up(Loc l) {                                                 /* rebuild the parent once */
    Frame f = l.path.back(); l.path.pop_back();
    auto kids = std::get<std::vector<NodePtr>>(f.parent->payload);  /* copy of shared ptrs */
    kids.at(f.index) = l.focus;                                  /* siblings stay shared */
    return Loc{ f.parent, std::move(l.path) };
}

