struct Node { int parent = -1; std::vector<int> kids; std::string label; };
struct Cursor { int at; std::vector<int> path; };   /* path = ancestors, root first */

Cursor down(const std::vector<Node>& a, Cursor c) {
    c.path.push_back(c.at);
    return Cursor{ a[c.at].kids.front(), std::move(c.path) };
}
Cursor up(const std::vector<Node>&, Cursor c) {
    int p = c.path.back(); c.path.pop_back();
    return Cursor{ p, std::move(c.path) };
}
void retitle(std::vector<Node>& a, Cursor c, std::string v) { a[c.at].label = std::move(v); }
